/* Controlled browser fixtures generated by the real solver/validator; no cloud calls. */
const { chromium } = require(process.env.PLAYWRIGHT_MODULE || 'playwright');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const f = JSON.parse(fs.readFileSync('work/d1-ui-fixtures.json'));
(async () => {
  const browser = await chromium.launch({ headless: true, channel: 'chrome' });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  let revised = false, blocked = false, drafts = 0, confirmations = 0;
  const errors = [];
  page.on('pageerror', () => errors.push('browser error'));
  await page.route('https://cognito-idp.*.amazonaws.com/**', r => r.fulfill({ json: { AuthenticationResult: { AccessToken: 'SYNTHETIC_TEST_ONLY', RefreshToken: 'SYNTHETIC_TEST_ONLY', ExpiresIn: 900 } } }));
  await page.route('**/api/**', async r => {
    const p = new URL(r.request().url()).pathname.slice(4);
    let value;
    if (p === '/auth/config') value = { region: 'ap-southeast-2', pool_id: 'SYNTHETIC', client_id: 'SYNTHETIC' };
    else if (p === '/me') value = f.admin;
    else if (p === '/inputs') {
      if (r.request().method() === 'POST') {
        const body = r.request().postDataJSON();
        assert.equal(body.expected_revision, revised ? f.revised_input.revision : f.room_input.revision);
        assert.deepEqual(body.input.activities, f.room_input.input.activities);
        assert.deepEqual(body.input.rooms.find(v => v.id === (revised ? 'movement-hall' : f.excluded_room)).available_period_ids, []);
        blocked = revised;
        confirmations++; revised = true;
      }
      value = blocked ? f.blocked_input : revised ? f.revised_input : f.room_input;
    } else if (p.startsWith('/inputs/')) value = f.room_input;
    else if (p === '/current-plan') value = { ...f.room_current, needs_review: revised, input_revision: revised ? f.revised_input.revision : f.room_input.revision };
    else if (p === '/approved-plans') value = f.room_history;
    else if (p === '/policy-excerpts') value = f.policies;
    else if (p === '/evidence/forecast') value = f.evidence;
    else if (p === '/draft-plans') { drafts++; assert(revised); assert.deepEqual(r.request().postDataJSON(), (blocked ? f.blocked_input : f.revised_input).input); value = blocked ? f.blocked_plan : f.revised_plan; }
    else if (p.startsWith('/draft-plans/')) value = p.endsWith(f.room_plan.id) ? f.room_plan : f.revised_plan;
    else if (p.endsWith('/review')) value = f.room_review;
    else if (p.startsWith('/approved-plans/')) value = f.room_detail;
    else return r.fulfill({ status: 404, json: { detail: 'Controlled route absent' } });
    await r.fulfill({ json: value });
  });
  try {
    await page.goto('http://127.0.0.1:5174');
    await page.getByLabel('Username', { exact: true }).fill('synthetic-admin');
    await page.getByLabel('Password', { exact: true }).fill('SYNTHETIC INPUT NOT A CREDENTIAL');
    await page.getByRole('button', { name: 'Sign in', exact: true }).click();
    await page.getByRole('heading', { name: 'Implementation', exact: true }).waitFor();
    assert((await page.locator('.today-schedule-row').first().boundingBox()).y < 900);
    assert((await page.locator('.plan-numbers').boundingBox()).y < 900);
    assert(await page.locator('.hourly-chart svg').count());
    assert(await page.evaluate(() => getComputedStyle(document.body).fontSize === '16px'));
    assert(await page.locator('.topbar .demo-label').evaluate(e => getComputedStyle(e).fontSize === '16px'));
    for (const width of [1440, 390]) {
      await page.setViewportSize({ width, height: width === 1440 ? 900 : 844 });
      assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1));
      await page.screenshot({ path: `${process.env.AIRWISE_SCREENSHOT_DIR || 'work'}/room-today-${width}.png`, fullPage: true });
    }
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.getByRole('link', { name: 'Plan comparison', exact: true }).click();
    await page.getByRole('button', { name: 'Approval recorded', exact: true }).waitFor();
    await page.getByLabel('Room to exclude', { exact: true }).selectOption(f.excluded_room);
    assert(await page.getByRole('button', { name: 'Generate room-change draft', exact: true }).isDisabled());
    await page.getByLabel('I confirm this sample room is unavailable for the affected day.').check();
    await page.getByRole('button', { name: 'Generate room-change draft', exact: true }).click();
    await page.getByText('Room change confirmed and revised draft generated.', { exact: false }).waitFor();
    assert.equal(confirmations, 1); assert.equal(drafts, 1);
    await page.waitForFunction(() => [...document.querySelectorAll('button')].some(b => b.textContent.trim() === 'Approve this version' && !b.disabled));
    assert.equal(f.room_current.plan_version, f.room_plan.id);
    assert(f.revised_plan.validation.valid && f.revised_plan.placements.every(p => p.room_id !== f.excluded_room));
    await page.locator('.scenario-result').waitFor();
    for (const width of [1440, 390]) {
      await page.setViewportSize({ width, height: width === 1440 ? 900 : 844 });
      assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1));
      const rect = await page.getByRole('button', { name: 'Sign out', exact: true }).boundingBox();
      assert(rect && rect.x + rect.width <= width);
      await page.screenshot({ path: `${process.env.AIRWISE_SCREENSHOT_DIR || 'work'}/room-plan-${width}.png`, fullPage: true });
    }
    await page.getByLabel('Room to exclude', { exact: true }).selectOption('movement-hall');
    await page.getByLabel('I confirm this sample room is unavailable for the affected day.').check();
    await page.getByRole('button', { name: 'Generate room-change draft', exact: true }).click();
    await page.getByText('No permitted timetable is feasible', { exact: true }).waitFor();
    await page.getByText('Class 7A has a fixed lesson', { exact: false }).waitFor();
    assert(await page.getByRole('button', { name: 'Approve this version', exact: true }).isDisabled());
    assert.equal(f.blocked_plan.solver_status, 'INFEASIBLE');
    assert.equal(confirmations, 2); assert.equal(drafts, 2);
    await page.getByRole('link', { name: 'Evidence & restrictions', exact: true }).click();
    await page.locator('.policy').first().waitFor();
    for (const width of [1440, 390]) {
      await page.setViewportSize({ width, height: width === 1440 ? 900 : 844 });
      assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1));
      await page.screenshot({ path: `${process.env.AIRWISE_SCREENSHOT_DIR || 'work'}/room-evidence-${width}.png`, fullPage: true });
    }
    assert.equal(errors.length, 0);
    console.log('PASS: first-screen decision/timetable, secondary chart, desktop/mobile, confirmed exclusion, independently validated actual repair fixture, one revision/draft, separate approval. Offline only.');
  } finally { await browser.close(); }
})().catch(e => { console.log('FAIL: room browser check (' + e.name + ')'); console.log(e.stack.split('\n').filter(l => l.includes('check_room.cjs')).join('\n')); process.exitCode = 1; });
